-- >>>>>>>>>>>>>>>>>>>>  tables/00_admin_config.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Admin config: tier subscription + tax settings
-- Created FIRST — seller_profiles.tier and order snapshots FK / read from here.
-- ============================================================

create table public.admin_tier_config (
  tier            text    not null,
  commission_rate numeric not null,
  monthly_fee_usd numeric not null default 0,
  max_items       integer,      -- null = unlimited
  max_categories  integer,      -- null = unlimited
  constraint admin_tier_config_pkey primary key (tier)
);

insert into public.admin_tier_config (tier, commission_rate, monthly_fee_usd, max_items, max_categories)
values
  ('founding',   0,    0,  null, null),  -- 0% commission, early adopter sellers
  ('community',  0.19, 0,  3,    1),
  ('tindahan',   0.17, 29, 30,   5),
  ('negosyo',    0.15, 49, 90,   10),
  ('enterprise', 0.13, 89, null, null),
  ('bodega',     0,    0,  null, null)   -- negotiated: rate set via seller_profiles.commission_rate_override
on conflict (tier) do nothing;

comment on table public.admin_tier_config is
  'Source of truth for tier definitions. Changing commission_rate here does NOT affect past orders.';
comment on column public.admin_tier_config.commission_rate is
  'Default rate for this tier. Bodega = 0 because rate is negotiated per seller.';


create table public.admin_tax_config (
  key         text        not null,
  rate        numeric     not null,
  description text,
  updated_at  timestamptz not null default now(),
  constraint admin_tax_config_pkey primary key (key)
);

insert into public.admin_tax_config (key, rate, description)
values
  ('vat_rate',                   0.10,        'VAT on Sariko commission (platform service fee to sellers)'),
  ('withholding_rate_goods',     0.01,        'Withholding tax for goods sellers (imported products, dry goods)'),
  ('withholding_rate_services',  0.02,        'Withholding tax for service sellers (food, tutoring, tailoring)'),
  ('annual_revenue_threshold',   100000000,   'Annual VND threshold above which withholding tax applies')
on conflict (key) do nothing;

comment on table public.admin_tax_config is
  'Platform-wide tax settings. Adjustable by admin. Changes apply to new orders only.';


-- >>>>>>>>>>>>>>>>>>>>  tables/01_users.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Users + user addresses
-- public.users.id mirrors auth.users.id (populated by the handle_user_create
-- trigger in functions/functions.sql).
-- ============================================================

create table public.users (
  id uuid not null default gen_random_uuid (),
  email text not null,
  name text null,
  phone text null,
  role text null default 'customer'::text,
  created_at timestamp without time zone null default now(),
  is_seller boolean null default false,
  updated_at timestamp without time zone null default now(),
  avatar_url text null,
  preferred_language text null,
  constraint users_pkey primary key (id),
  constraint users_email_key unique (email),
  constraint users_role_check check (
    (role = any (array['customer'::text, 'seller'::text]))
  )
) TABLESPACE pg_default;


create table public.user_addresses (
  id bigint generated by default as identity not null,
  user_id uuid not null,
  label text null,
  address text not null,
  lat double precision null,
  lon double precision null,
  is_default boolean not null default false,
  created_at timestamp with time zone not null default now(),
  constraint user_addresses_pkey primary key (id),
  constraint user_addresses_user_id_fkey foreign KEY (user_id) references users (id) on update CASCADE on delete CASCADE
) TABLESPACE pg_default;


-- >>>>>>>>>>>>>>>>>>>>  tables/02_seller_profiles.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Seller profiles
-- tier FK → admin_tier_config; status coming_soon | active.
-- ============================================================

create table public.seller_profiles (
  id uuid not null default gen_random_uuid (),
  user_id uuid null,
  store_name text not null,
  description text null,
  avatar_url text null,
  cover_url text null,
  address text null,
  lat numeric null,
  lon numeric null,
  is_open boolean null default true,
  opening_time time without time zone null,
  closing_time time without time zone null,
  is_verified boolean null default false,
  created_at timestamp without time zone null default now(),
  slug text not null,
  phone text null,
  tier text not null default 'community'::text,
  commission_rate_override numeric null,
  bank_account_number text null,
  bank_name text null,
  bank_account_holder text null,
  tax_category text not null default 'services'::text,
  status text not null default 'coming_soon'::text,
  rating_avg numeric null,
  rating_count integer not null default 0,
  is_listed boolean not null default true,
  display_order integer not null default 0,
  constraint seller_profiles_pkey primary key (id),
  constraint seller_profiles_slug_key unique (slug),
  constraint seller_profiles_tier_fkey foreign KEY (tier) references admin_tier_config (tier),
  constraint seller_profiles_user_id_fkey foreign KEY (user_id) references users (id) on delete CASCADE,
  constraint seller_profiles_tax_category_check check (
    (tax_category = any (array['goods'::text, 'services'::text]))
  ),
  constraint seller_profiles_status_check check (
    (status = any (array['coming_soon'::text, 'active'::text]))
  )
) TABLESPACE pg_default;

create index IF not exists idx_seller_location on public.seller_profiles using btree (lat, lon) TABLESPACE pg_default;

comment on column public.seller_profiles.commission_rate_override is
  'Only set for bodega tier. NULL = use admin_tier_config.commission_rate.';
comment on column public.seller_profiles.rating_avg is
  'Denormalised from reviews (overall rows only, food_item_id is null). Maintained by
   the on_review_change trigger — never write it by hand. NULL until the first review.';
comment on column public.seller_profiles.is_listed is
  'Admin curation: false = hidden from the public seller list and from featured dishes.
   Distinct from status (lifecycle: coming_soon | active) and is_open (opening hours) —
   a seller can be active + open and still be unlisted. The storefront stays reachable
   by direct slug URL; this only controls discovery.';
comment on column public.seller_profiles.display_order is
  'Manual sort within the seller list, ascending (lower first). Applied after status,
   so it orders sellers within the active block and within the coming_soon block.
   Ties break by created_at.';


-- >>>>>>>>>>>>>>>>>>>>  tables/03_menu.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Menu: categories + food items (both scoped to a seller_profile)
-- ============================================================

create table public.menu_categories (
  id uuid not null default gen_random_uuid (),
  seller_id uuid null,
  name text not null,
  sort_order integer null default 0,
  is_active boolean null default true,
  created_at timestamp without time zone null default now(),
  updated_at timestamp without time zone null default now(),
  constraint menu_categories_pkey primary key (id),
  constraint menu_categories_seller_id_fkey foreign KEY (seller_id) references seller_profiles (id) on delete CASCADE
) TABLESPACE pg_default;


create table public.food_items (
  id uuid not null default gen_random_uuid (),
  seller_id uuid null,
  category_id uuid null,
  name text not null,
  description text null,
  price numeric not null,
  unit_label text null,
  min_quantity integer null default 1,
  quantity_step integer null default 1,
  preorder_day integer null default 0,
  is_available boolean null default true,
  image_url text null,
  created_at timestamp without time zone null default now(),
  price_text text null,
  is_featured boolean not null default false,
  rating_avg numeric null,
  rating_count integer not null default 0,
  constraint food_items_pkey primary key (id),
  constraint food_items_category_id_fkey foreign KEY (category_id) references menu_categories (id) on delete set null,
  constraint food_items_seller_id_fkey foreign KEY (seller_id) references seller_profiles (id) on delete CASCADE
) TABLESPACE pg_default;

create index IF not exists idx_food_items_seller on public.food_items using btree (seller_id) TABLESPACE pg_default;

comment on column public.food_items.rating_avg is
  'Denormalised from reviews (per-dish rows only). Maintained by the on_review_change
   trigger — never write it by hand. NULL until the first review.';


-- ============================================================
-- Price variants: one required, single-select level per dish
-- (added 2026-08-24 — archive/20260824_food_item_variants.sql)
-- ============================================================

create table public.food_item_variants (
  id uuid not null default gen_random_uuid (),
  food_item_id uuid not null,
  name text not null,
  price numeric not null,
  price_text text null,
  sort_order integer not null default 0,
  is_available boolean not null default true,
  created_at timestamp without time zone null default now(),
  constraint food_item_variants_pkey primary key (id),
  constraint food_item_variants_food_item_id_fkey foreign KEY (food_item_id) references food_items (id) on delete CASCADE,
  -- The name is what the buyer picks by and what gets snapshotted onto the order.
  constraint food_item_variants_food_item_id_name_key unique (food_item_id, name),
  constraint food_item_variants_price_check check ((price >= (0)::numeric))
) TABLESPACE pg_default;

create index IF not exists idx_food_item_variants_item on public.food_item_variants using btree (food_item_id) TABLESPACE pg_default;

comment on table public.food_item_variants is
  'One row per selectable price level of a dish ("S"/"M"/"L", "1 người"/"4 người").
   Exactly one must be chosen when the dish has variants — this is not a topping /
   add-on model, nothing here is cumulative. There is deliberately NO group-label
   column on food_items: the presence of rows here is the single source of truth
   for "does this dish have levels?", and the UI heading is a translated string in
   the frontend rather than seller-typed text no locale file can reach.';

comment on column public.food_item_variants.price is
  'ABSOLUTE price of this level, NOT a delta on food_items.price. No code path adds
   the two together. This is what keeps order_items.price_snapshot meaning "final
   unit price paid", so every price_snapshot * quantity on the frontend stays valid.';

comment on column public.food_item_variants.price_text is
  'Display string derived from price by _make_price_text() in apis/sellers.py.
   Same contract as food_items.price_text — never write it by hand.';


-- >>>>>>>>>>>>>>>>>>>>  tables/04_carts.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Carts + cart items (one active cart per user, single-seller)
-- ============================================================

create table public.carts (
  id uuid not null default gen_random_uuid (),
  user_id uuid null,
  seller_id uuid null,
  created_at timestamp without time zone null default now(),
  constraint carts_pkey primary key (id),
  constraint carts_seller_id_fkey foreign KEY (seller_id) references seller_profiles (id),
  constraint carts_user_id_fkey foreign KEY (user_id) references users (id) on delete CASCADE,
  -- One active cart per user. Without this, two concurrent /cart/add requests both
  -- read "no cart" and both insert, and every later .eq(user_id) singular read breaks.
  constraint carts_user_id_key unique (user_id)
) TABLESPACE pg_default;


create table public.cart_items (
  id uuid not null default gen_random_uuid (),
  cart_id uuid null,
  food_item_id uuid null,
  variant_id uuid null,
  quantity integer not null,
  constraint cart_items_pkey primary key (id),
  constraint cart_items_cart_id_fkey foreign KEY (cart_id) references carts (id) on delete CASCADE,
  constraint cart_items_food_item_id_fkey foreign KEY (food_item_id) references food_items (id),
  -- No ON DELETE, same as the food_items FK: a variant sitting in someone's cart
  -- must not vanish underneath them. Retire levels with is_available instead.
  constraint cart_items_variant_id_fkey foreign KEY (variant_id) references food_item_variants (id),
  constraint cart_items_quantity_check check ((quantity > 0))
) TABLESPACE pg_default;

-- One row per (cart, dish, level); quantity carries the count. Same race as carts.
-- Two PARTIAL indexes rather than one `unique nulls not distinct (...)`: that form
-- needs PG 15+ and the server version could not be verified from the dev machine
-- (see archive/20260820_cart_uniqueness.sql). These work on every version and say
-- the intent plainly — with a level, unique per level; without one, unique per dish.
create unique index IF not exists cart_items_dish_variant_key
  on public.cart_items using btree (cart_id, food_item_id, variant_id)
  where variant_id is not null;

create unique index IF not exists cart_items_dish_novariant_key
  on public.cart_items using btree (cart_id, food_item_id)
  where variant_id is null;

comment on column public.cart_items.variant_id is
  'NULL for dishes without variants. The cart holds a REFERENCE, never a snapshot:
   the unit price is read live from food_item_variants.price (or food_items.price
   when NULL) on every cart read, so a seller price change is reflected at once.';


-- >>>>>>>>>>>>>>>>>>>>  tables/05_admin_payouts.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Admin payout batches — one row per weekly payout run per seller.
-- Created BEFORE orders because orders.payout_id references it.
-- ============================================================

create table public.admin_payouts (
  id                 uuid        not null default gen_random_uuid(),
  seller_id          uuid        not null,  -- FK → seller_profiles.id
  period_start       date        not null,
  period_end         date        not null,
  order_count        integer     not null default 0,
  total_subtotal     numeric     not null default 0,
  total_commission   numeric     not null default 0,
  total_vat          numeric     not null default 0,
  gross_payout       numeric     not null default 0,  -- subtotal - commission - vat
  withholding_rate   numeric     not null default 0,  -- snapshot at payout time
  withholding_amount numeric     not null default 0,
  net_payout         numeric     not null default 0,  -- gross_payout - withholding
  status             text        not null default 'pending'
    constraint admin_payouts_status_check check (
      status = any (array['pending', 'processing', 'completed', 'failed'])
    ),
  note               text,
  paid_at            timestamptz,
  created_at         timestamptz not null default now(),
  constraint admin_payouts_pkey primary key (id),
  constraint admin_payouts_seller_id_fkey foreign KEY (seller_id) references public.seller_profiles (id)
);

create index IF not exists idx_admin_payouts_seller_id on public.admin_payouts (seller_id);
create index IF not exists idx_admin_payouts_status on public.admin_payouts (status);

comment on table public.admin_payouts is
  'Weekly payout batch per seller. One row = one bank transfer to seller.';


-- >>>>>>>>>>>>>>>>>>>>  tables/06_orders.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Orders + order items (snapshot)
-- Commission + VAT are snapshotted at creation and never change after insert.
-- payout_amount = subtotal - commission_amount - vat_amount (delivery fee excluded).
-- ============================================================

create table public.orders (
  id uuid not null default gen_random_uuid (),
  user_id uuid null,
  seller_id uuid null,
  status text null default 'pending'::text,
  total_amount numeric not null,
  delivery_fee numeric null default 0,
  payment_status text null default 'pending'::text,
  delivery_method text null,
  delivery_address text null,
  note text null,
  created_at timestamp without time zone null default now(),
  delivery_lat double precision null,
  delivery_lon double precision null,
  quotation_id text null,
  cancellation_reason text null,
  transaction_ref text null,
  seller_user_id uuid null,
  subtotal numeric not null default 0,
  commission_rate numeric not null default 0,   -- snapshot from seller tier
  commission_amount numeric not null default 0,
  payout_amount numeric not null default 0,
  payout_status text not null default 'pending'::text,
  payout_id uuid null,
  vat_rate numeric not null default 0,           -- snapshot from admin_tax_config
  vat_amount numeric not null default 0,
  ipn_data jsonb null,
  delivery_appointment timestamp with time zone null,
  payment_create_date text null,
  constraint orders_pkey primary key (id),
  constraint orders_payout_id_fkey foreign KEY (payout_id) references admin_payouts (id) on delete set null,
  constraint orders_user_id_fkey foreign KEY (user_id) references users (id),
  constraint orders_seller_id_fkey foreign KEY (seller_id) references seller_profiles (id),
  constraint orders_payment_status_check check (
    (payment_status = any (array['pending'::text, 'paid'::text, 'failed'::text]))
  ),
  constraint orders_delivery_method_check check (
    (delivery_method = any (array['pickup'::text, 'delivery'::text]))
  ),
  constraint orders_status_check check (
    (status = any (
      array[
        'pending'::text, 'confirmed'::text, 'ready'::text,
        'done'::text, 'cancelled'::text, 'delivery_failed'::text
      ]
    ))
  ),
  constraint orders_payout_status_check check (
    (payout_status = any (array['pending'::text, 'processing'::text, 'paid_out'::text]))
  )
) TABLESPACE pg_default;

create index IF not exists idx_orders_user on public.orders using btree (user_id) TABLESPACE pg_default;
create index IF not exists idx_orders_seller on public.orders using btree (seller_id) TABLESPACE pg_default;


create table public.order_items (
  id uuid not null default gen_random_uuid (),
  order_id uuid null,
  food_item_id uuid null,
  name_snapshot text null,
  price_snapshot numeric null,
  unit_label_snapshot text null,
  variant_name_snapshot text null,
  quantity integer not null,
  constraint order_items_pkey primary key (id),
  constraint order_items_food_item_id_fkey foreign KEY (food_item_id) references food_items (id),
  constraint order_items_order_id_fkey foreign KEY (order_id) references orders (id) on delete CASCADE
) TABLESPACE pg_default;

-- Every order detail read embeds order_items, and that page polls every 10s.
create index IF not exists idx_order_items_order on public.order_items using btree (order_id) TABLESPACE pg_default;

comment on column public.order_items.variant_name_snapshot is
  'Variant name at order time — "L", "4 người". Display and reconciliation only:
   price_snapshot already carries the FINAL unit price of that variant, so all
   existing price_snapshot * quantity arithmetic is unchanged.
   Deliberately no variant_id FK — a snapshot must never block a seller from
   deleting a variant, and nothing joins back to the variant row.';


-- >>>>>>>>>>>>>>>>>>>>  tables/07_reviews.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Reviews (buyer rates a completed order)
-- One submit writes 1 + N rows, distinguished by food_item_id:
--   food_item_id IS NULL     → the order's overall rating  → seller_profiles.rating_avg
--   food_item_id IS NOT NULL → a per-dish rating           → food_items.rating_avg
-- Overall rows carry no comment by design; per-dish comments are optional.
-- ============================================================

create table public.reviews (
  id uuid not null default gen_random_uuid (),
  order_id uuid null,
  seller_id uuid null,
  user_id uuid null,
  food_item_id uuid null,
  rating integer null,
  comment text null,
  created_at timestamp without time zone null default now(),
  constraint reviews_pkey primary key (id),
  constraint reviews_order_id_fkey foreign KEY (order_id) references orders (id) on delete CASCADE,
  constraint reviews_seller_id_fkey foreign KEY (seller_id) references seller_profiles (id),
  constraint reviews_user_id_fkey foreign KEY (user_id) references users (id),
  constraint reviews_food_item_id_fkey foreign KEY (food_item_id) references food_items (id) on delete CASCADE,
  constraint reviews_rating_check check (((rating >= 1) and (rating <= 5)))
) TABLESPACE pg_default;

-- Uniqueness is split in two on purpose: Postgres treats every NULL as distinct, so a
-- plain unique (order_id, food_item_id) would happily accept two overall rows per order.
create unique index if not exists uniq_review_order_item
  on public.reviews (order_id, food_item_id)
  where food_item_id is not null;

create unique index if not exists uniq_review_order_overall
  on public.reviews (order_id)
  where food_item_id is null;

-- order_id is the hottest lookup (orders-list embed, order detail, review submit) and
-- Postgres does not index FK columns automatically. The two partial unique indexes
-- above cannot serve a bare order_id = ? lookup: each covers only half the rows.
create index if not exists idx_reviews_order on public.reviews using btree (order_id) TABLESPACE pg_default;
create index if not exists idx_reviews_food_item on public.reviews using btree (food_item_id) TABLESPACE pg_default;
create index if not exists idx_reviews_seller on public.reviews using btree (seller_id) TABLESPACE pg_default;


-- >>>>>>>>>>>>>>>>>>>>  tables/08_deliveries.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Deliveries (Lalamove booking + driver tracking, per order)
-- ============================================================

create table public.deliveries (
