  status text null,
  tracking_url text null,
  driver_name text null,
  driver_phone text null,
  created_at timestamp without time zone null default now(),
  estimated_pickup_time timestamp without time zone null,
  share_link text null,
  driver_plate text null,
  lalamove_order_id text null,
  rebook_count integer null default 0,
  user_id uuid null,
  seller_user_id uuid null,
  constraint deliveries_pkey primary key (id),
  constraint deliveries_order_id_fkey foreign KEY (order_id) references orders (id) on delete CASCADE,
  constraint deliveries_seller_user_id_fkey foreign KEY (seller_user_id) references users (id),
  constraint deliveries_user_id_fkey foreign KEY (user_id) references users (id)
) TABLESPACE pg_default;

create index IF not exists idx_deliveries_order_id on public.deliveries using btree (order_id) TABLESPACE pg_default;
create index IF not exists idx_deliveries_lalamove_order_id on public.deliveries using btree (lalamove_order_id) TABLESPACE pg_default;
create index IF not exists idx_deliveries_user_id on public.deliveries using btree (user_id) TABLESPACE pg_default;
create index IF not exists idx_deliveries_seller_user_id on public.deliveries using btree (seller_user_id) TABLESPACE pg_default;


-- >>>>>>>>>>>>>>>>>>>>  tables/09_refunds.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Refunds (VNPay refund tracking) — created before payments (payments.refund_id FK).
-- ============================================================

create table public.refunds (
  id uuid not null default gen_random_uuid (),
  order_id uuid not null,
  amount numeric not null,
  reason text not null,
  status text not null default 'pending'::text,
  original_txn_ref text null,
  ipn_data jsonb null,
  vnpay_refund_ref text null,
  created_at timestamp with time zone null default now(),
  processed_at timestamp with time zone null,
  note text null,
  payment_create_date text null,
  constraint refunds_pkey primary key (id),
  constraint refunds_order_id_fkey foreign KEY (order_id) references orders (id),
  constraint refunds_reason_check check (
    (reason = any (array['buyer_cancel'::text, 'driver_booking_failed'::text]))
  ),
  constraint refunds_status_check check (
    (status = any (array['pending'::text, 'processed'::text, 'failed'::text]))
  )
) TABLESPACE pg_default;


-- >>>>>>>>>>>>>>>>>>>>  tables/10_payments.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Payments (VNPay charge / refund records)
-- ============================================================

create table public.payments (
  id uuid not null default gen_random_uuid (),
  order_id uuid null,
  method text null,
  amount numeric null,
  status text null,
  transaction_ref text null,
  created_at timestamp without time zone null default now(),
  type text not null default 'charge'::text,
  vnp_transaction_no text null,
  refund_id uuid null,
  constraint payments_pkey primary key (id),
  constraint payments_order_id_fkey foreign KEY (order_id) references orders (id) on delete CASCADE,
  constraint payments_refund_id_fkey foreign KEY (refund_id) references refunds (id) on delete set null,
  constraint payments_type_check check (
    (type = any (array['charge'::text, 'refund'::text]))
  )
) TABLESPACE pg_default;


-- >>>>>>>>>>>>>>>>>>>>  tables/11_chat.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Chat: buyer <-> seller messaging. One conversation per (buyer, seller) pair.
-- Named chat_* on purpose — Supabase ships realtime.messages already.
-- Pin / soft-delete are per participant (buyer_* and seller_* columns).
--
-- The bump trigger lives in functions/functions.sql; grants, realtime
-- publication, and RLS live in policies/rls.sql.
-- ============================================================

create table public.chat_conversations (
  id uuid not null default gen_random_uuid (),
  buyer_id uuid not null,
  seller_id uuid not null,
  last_message_at timestamp with time zone null,
  last_message_text text null,
  buyer_pinned_at timestamp with time zone null,
  seller_pinned_at timestamp with time zone null,
  buyer_deleted_at timestamp with time zone null,
  seller_deleted_at timestamp with time zone null,
  created_at timestamp with time zone not null default now(),
  constraint chat_conversations_pkey primary key (id),
  constraint chat_conversations_buyer_seller_key unique (buyer_id, seller_id),
  constraint chat_conversations_buyer_id_fkey foreign KEY (buyer_id) references users (id) on delete CASCADE,
  constraint chat_conversations_seller_id_fkey foreign KEY (seller_id) references seller_profiles (id) on delete CASCADE
) TABLESPACE pg_default;

create index IF not exists idx_chat_conversations_buyer on public.chat_conversations using btree (buyer_id) TABLESPACE pg_default;
create index IF not exists idx_chat_conversations_seller on public.chat_conversations using btree (seller_id) TABLESPACE pg_default;


create table public.chat_messages (
  id uuid not null default gen_random_uuid (),
  conversation_id uuid not null,
  sender_id uuid not null,
  body text not null,
  created_at timestamp with time zone not null default now(),
  read_at timestamp with time zone null,
  constraint chat_messages_pkey primary key (id),
  constraint chat_messages_conversation_id_fkey foreign KEY (conversation_id) references chat_conversations (id) on delete CASCADE,
  constraint chat_messages_sender_id_fkey foreign KEY (sender_id) references users (id),
  constraint chat_messages_body_check check ((char_length(btrim(body)) > 0))
) TABLESPACE pg_default;

create index IF not exists idx_chat_messages_conversation on public.chat_messages using btree (conversation_id, created_at desc) TABLESPACE pg_default;


-- >>>>>>>>>>>>>>>>>>>>  functions/functions.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Functions & triggers
-- The trigger that binds handle_user_create to auth.users is managed in the
-- Supabase dashboard (Auth hooks), not here.
-- ============================================================

-- ⚠️ WARNING: the two handle_user_create definitions below share the SAME name,
-- so the second CREATE OR REPLACE OVERWRITES the first — only the UPDATE body
-- survives. This looks like a latent bug (the INSERT-on-signup body is lost).
-- Preserved verbatim from the original functions.sql; review before relying on it.

-- Insert a public.users row after auth.users creates a record.
create or replace function public.handle_user_create()
returns trigger as
$$
begin
    if not exists (select 1 from public.users where id = new.id) then
        insert into public.users (
          id, email, name, is_seller, created_at, updated_at
        ) values (
            new.id,
            new.email,
            new.raw_user_meta_data->>'fullname',
            new.raw_user_meta_data->>'is_seller',
            new.created_at,
            new.updated_at
        );
    end if;
    return new;
end;
$$
language plpgsql security definer;

-- Sync avatar/phone from auth metadata (⚠️ overwrites the definition above).
create or replace function public.handle_user_create()
returns trigger as
$$
begin
    update public.users
    set
        avatar_url = new.raw_user_meta_data->>'avatar_url',
        phone = new.phone,
        updated_at = new.updated_at
    where id = new.id;
    return new;
end;
$$
language plpgsql security definer;


-- Update order + payment status together (used by the VNPay flow).
create or replace function update_order_payment_status(
  p_order_id uuid,
  p_status text,
  p_transaction_ref text default null
) returns void as
$$
begin
  update public.orders
  set payment_status = p_status
  where id = p_order_id;

  if p_transaction_ref is not null then
    update public.payments
    set status = p_status, transaction_ref = p_transaction_ref
    where order_id = p_order_id;
  end if;
end;
$$
language plpgsql security definer
set search_path = public;


-- Chat: on a new message, refresh the conversation preview / ordering columns
-- AND resurface the thread for anyone who had soft-deleted it (new activity un-hides).
-- SECURITY DEFINER so an authenticated message insert can update the parent
-- conversation without needing an UPDATE grant / RLS policy on that role.
create or replace function public.bump_chat_conversation () returns trigger
  language plpgsql
  security definer
  set search_path = public
as $$
begin
  update public.chat_conversations
     set last_message_at = new.created_at,
         last_message_text = new.body,
         buyer_deleted_at = null,
         seller_deleted_at = null
   where id = new.conversation_id;
  return new;
end;
$$;

drop trigger if exists on_new_chat_message on public.chat_messages;
create trigger on_new_chat_message
  after insert on public.chat_messages
  for each row
  execute function public.bump_chat_conversation ();


-- Reviews: keep the denormalised rating columns in sync so every menu query can read
-- rating_avg / rating_count inline instead of aggregating per request.
-- A review row rolls up to exactly one place: per-dish rows (food_item_id not null) to
-- food_items, overall rows to seller_profiles. The averages are recomputed from scratch
-- rather than adjusted incrementally, so hand-deleting test rows self-heals.
-- The API only ever inserts; update/delete are covered for manual cleanup in the SQL editor.
create or replace function public.recalc_review_ratings () returns trigger
  language plpgsql
  security definer
  set search_path = public
as $$
declare
  v_food_item_id uuid;
  v_seller_id    uuid;
begin
  -- NEW is unassigned on DELETE, so pick the source row explicitly.
  if tg_op = 'DELETE' then
    v_food_item_id := old.food_item_id;
    v_seller_id    := old.seller_id;
  else
    v_food_item_id := new.food_item_id;
    v_seller_id    := new.seller_id;
  end if;

  if v_food_item_id is not null then
    update public.food_items f
       set rating_avg   = sub.avg_rating,
           rating_count = sub.cnt
      from (
        select round(avg(rating)::numeric, 1) as avg_rating,
               count(*)                       as cnt
          from public.reviews
         where food_item_id = v_food_item_id
      ) sub
     where f.id = v_food_item_id;

  elsif v_seller_id is not null then
    update public.seller_profiles s
       set rating_avg   = sub.avg_rating,
           rating_count = sub.cnt
      from (
        select round(avg(rating)::numeric, 1) as avg_rating,
               count(*)                       as cnt
          from public.reviews
         where seller_id = v_seller_id
           and food_item_id is null
      ) sub
     where s.id = v_seller_id;
  end if;

  return null;
end;
$$;

drop trigger if exists on_review_change on public.reviews;
create trigger on_review_change
  after insert or update or delete on public.reviews
  for each row
  execute function public.recalc_review_ratings ();


-- >>>>>>>>>>>>>>>>>>>>  policies/rls.sql  <<<<<<<<<<<<<<<<<<<<

-- ============================================================
-- Row Level Security — all policies, organized by table.
-- Clients (authenticated) read/write some tables directly via Supabase;
-- everything else goes through the backend (service_role, bypasses RLS).
-- Idempotent: every policy is dropped-if-exists before create.
--
-- NOTE: image uploads no longer use storage RLS — they go through backend
-- endpoints (service role). See archive/storage_policies.sql for the retired
-- storage.objects policies. Storage reads stay public via the bucket setting.
-- ============================================================

alter table public.users enable row level security;
alter table public.seller_profiles enable row level security;
alter table public.menu_categories enable row level security;
alter table public.food_items enable row level security;
alter table public.food_item_variants enable row level security;
alter table public.carts enable row level security;
alter table public.cart_items enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.reviews enable row level security;
alter table public.payments enable row level security;
alter table public.deliveries enable row level security;
alter table public.chat_conversations enable row level security;
alter table public.chat_messages enable row level security;

-- ── users ──────────────────────────────────────────────────────────────────
drop policy if exists "users can read own profile" on public.users;
create policy "users can read own profile"
on public.users for select
using (id = auth.uid());

drop policy if exists "users can update own profile" on public.users;
create policy "users can update own profile"
on public.users for update
using (id = auth.uid());

-- ── seller_profiles ────────────────────────────────────────────────────────
-- Public can browse storefronts; a seller edits only their own row.
-- NOTE: "public read" exposes every column (incl. user_id, phone) to anon.
-- Keep sensitive/column-shaped reads going through the backend.
drop policy if exists "seller read own profile" on public.seller_profiles;  -- superseded by public read
drop policy if exists "public read seller profiles" on public.seller_profiles;
create policy "public read seller profiles"
on public.seller_profiles for select
using (true);

drop policy if exists "seller update own profile" on public.seller_profiles;
create policy "seller update own profile"
on public.seller_profiles for update
using (user_id = auth.uid())
with check (user_id = auth.uid());

-- ── menu_categories ────────────────────────────────────────────────────────
drop policy if exists "public read categories" on public.menu_categories;
create policy "public read categories"
on public.menu_categories for select
using (true);

drop policy if exists "seller manage categories" on public.menu_categories;
create policy "seller manage categories"
on public.menu_categories for all
using (seller_id in (select id from public.seller_profiles where user_id = auth.uid()))
with check (seller_id in (select id from public.seller_profiles where user_id = auth.uid()));

-- ── food_items ─────────────────────────────────────────────────────────────
drop policy if exists "public read food" on public.food_items;
create policy "public read food"
on public.food_items for select
using (is_available = true);

drop policy if exists "seller manage food" on public.food_items;
create policy "seller manage food"
on public.food_items for all
using (seller_id in (select id from public.seller_profiles where user_id = auth.uid()))
with check (seller_id in (select id from public.seller_profiles where user_id = auth.uid()));

-- ── food_item_variants ─────────────────────────────────────────────────────
-- Mirrors food_items: a price level is no more sensitive than the dish price it
-- belongs to. Ownership is checked one hop up, through the parent dish.
drop policy if exists "public read variants" on public.food_item_variants;
create policy "public read variants"
on public.food_item_variants for select
using (is_available = true);

drop policy if exists "seller manage variants" on public.food_item_variants;
create policy "seller manage variants"
on public.food_item_variants for all
using (food_item_id in (
  select fi.id from public.food_items fi
  join public.seller_profiles sp on sp.id = fi.seller_id
  where sp.user_id = auth.uid()))
with check (food_item_id in (
  select fi.id from public.food_items fi
  join public.seller_profiles sp on sp.id = fi.seller_id
  where sp.user_id = auth.uid()));

-- ── carts / cart_items ─────────────────────────────────────────────────────
drop policy if exists "user manage own cart" on public.carts;
create policy "user manage own cart"
on public.carts for all
using (user_id = auth.uid())
with check (user_id = auth.uid());

drop policy if exists "user manage own cart items" on public.cart_items;
create policy "user manage own cart items"
on public.cart_items for all
using (cart_id in (select id from public.carts where user_id = auth.uid()))
with check (cart_id in (select id from public.carts where user_id = auth.uid()));

-- ── orders / order_items ───────────────────────────────────────────────────
drop policy if exists "user read own orders" on public.orders;
create policy "user read own orders"
on public.orders for select
using (
    user_id = auth.uid()
    or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
);

drop policy if exists "user create order" on public.orders;
create policy "user create order"
on public.orders for insert
with check (user_id = auth.uid());

drop policy if exists "seller update order status" on public.orders;
create policy "seller update order status"
on public.orders for update
using (seller_id in (select id from public.seller_profiles where user_id = auth.uid()));

drop policy if exists "read order items of accessible orders" on public.order_items;
create policy "read order items of accessible orders"
on public.order_items for select
using (
    order_id in (
        select id from public.orders
        where user_id = auth.uid()
        or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
    )
);

-- ── reviews ────────────────────────────────────────────────────────────────
drop policy if exists "public read reviews" on public.reviews;
create policy "public read reviews"
on public.reviews for select
using (true);

drop policy if exists "user write own review" on public.reviews;
create policy "user write own review"
on public.reviews for insert
with check (user_id = auth.uid());

-- ── payments ───────────────────────────────────────────────────────────────
drop policy if exists "user read own payments" on public.payments;
create policy "user read own payments"
on public.payments for select
using (order_id in (select id from public.orders where user_id = auth.uid()));

-- ── deliveries ─────────────────────────────────────────────────────────────
drop policy if exists "read delivery of accessible orders" on public.deliveries;
create policy "read delivery of accessible orders"
on public.deliveries for select
using (
    order_id in (
        select id from public.orders
        where user_id = auth.uid()
        or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
    )
);

-- ── chat ───────────────────────────────────────────────────────────────────
-- RLS filters rows, but the authenticated role still needs table privileges.
-- Frontend reads history + sends messages directly; it reads chat_conversations
-- because the message policies reference it in a subquery. No anon access.
grant select on public.chat_conversations to authenticated;
grant select, insert on public.chat_messages to authenticated;
grant all on public.chat_conversations to service_role;
grant all on public.chat_messages to service_role;

-- Broadcast message inserts to subscribed participants (RLS still filters rows).
do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'chat_messages'
  ) then
    alter publication supabase_realtime add table public.chat_messages;
  end if;
end $$;

drop policy if exists "participant read conversation" on public.chat_conversations;
create policy "participant read conversation"
on public.chat_conversations for select
using (
  buyer_id = auth.uid()
  or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
);

drop policy if exists "participant update conversation" on public.chat_conversations;
create policy "participant update conversation"
on public.chat_conversations for update
using (
  buyer_id = auth.uid()
  or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
);

drop policy if exists "participant read messages" on public.chat_messages;
create policy "participant read messages"
on public.chat_messages for select
using (
  conversation_id in (
    select id from public.chat_conversations
    where buyer_id = auth.uid()
       or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
  )
);

drop policy if exists "participant send message" on public.chat_messages;
create policy "participant send message"
on public.chat_messages for insert
with check (
  sender_id = auth.uid()
  and conversation_id in (
    select id from public.chat_conversations
    where buyer_id = auth.uid()
       or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
  )
);

drop policy if exists "recipient mark read" on public.chat_messages;
create policy "recipient mark read"
on public.chat_messages for update
using (
  conversation_id in (
    select id from public.chat_conversations
    where buyer_id = auth.uid()
       or seller_id in (select id from public.seller_profiles where user_id = auth.uid())
  )
);
